var moneyReq = JSON.parse(java.ajax("https://api.sfacg.com/user/money"))
var data = JSON.parse(java.ajax(baseUrl)).data
if (data.isVip && data.expand.needFireMoney <= (moneyReq.data.fireMoneyRemain + moneyReq.data.couponsRemain)) {
  java.toast(`\n数据获取：\nchapterId=${data.chapId}\nnovelId=${data.novelId}`)
  var chapId = parseInt(data.chapId)
  payObj = java.ajax(`https://api.sfacg.com/novels/${data.novelId}/orderedchaps,{method:"POST",body:'{"orderType":"readOrder","orderAll":false,"autoOrder":false,"chapIds":[${chapId}]}'}`)
  // java.toast(payObj)
  var res = JSON.parse(payObj)
  if (res.status.errorCode == 200) {
    var moneyReqNew = JSON.parse(java.ajax('https://api.sfacg.com/user/money'))
    java.toast(`购买成功，请刷新章节\n您目前剩余${moneyReqNew.data.fireMoneyRemain}火券，${moneyReqNew.data.couponsRemain}代券`)
    true
  } else if (res.status.errorCode == 671) {
  	  java.toast("章节已购买，请不要重复购买")
  	  true
    } else {
    java.toast("购买失败: " + payObj.data.msg)
    false
  }
} else {
  java.toast("您的余额不足，需要" + data.needFireMoney + "个火券，您还有" + moneyReq.data.fireMoneyRemain + "个火券，" + moneyReq.data.couponsRemain + "个代券")
  false
}

