function push(vc, a, b, c, d, e, f) {
    let list = c_Json[vc];
    if(!list) c_Json[vc] = list = [];
    // if (!e==1 || false) return
    list.push({
        "ChapterName": a || "",
        "isVolume": b || false,
        "chapterUrl": c ? b64Url(
          JSON.stringify({
            source: "qd",
            cid: c || null,
            isVip: e==1 || false,
            isPay: f==1 || false,
            ccid: null,
            cbid: null
          })) : "",
        "ChapterInfo": d || "",
        "isVip": e==1 || false,
